import * as THREE from 'three/webgpu';
import { texture, uv, vec2 } from 'three/tsl';

export default function createNode(config, ctx) {
  const group = new THREE.Group();
  group.name = 'hub-features-title';
  group.position.set(0, 3, 0);
  group.rotation.set(0, 0, 0);
  group.scale.set(1, 1, 1);

  const atlasRegion = { x: 0, y: 0, w: 512, h: 320, atlasW: 512, atlasH: 320 };
  const aspect = atlasRegion.w / atlasRegion.h;
  const planeHeight = 0.34; // headline scale unit em height
  const planeWidth = planeHeight * aspect;

  const geometry = new THREE.PlaneGeometry(planeWidth, planeHeight);

  const material = new THREE.MeshBasicNodeMaterial({
    transparent: true,
    depthWrite: false,
  });

  const disposers = [];

  const baseUV = uv();
  const uOffset = atlasRegion.x / atlasRegion.atlasW;
  const vOffset = 1.0 - (atlasRegion.y + atlasRegion.h) / atlasRegion.atlasH;
  const uScale = atlasRegion.w / atlasRegion.atlasW;
  const vScale = atlasRegion.h / atlasRegion.atlasH;

  const atlasUV = baseUV.mul(vec2(uScale, vScale)).add(vec2(uOffset, vOffset));

  const map = ctx.textureLoader.load('/prism-assets/chrome/ceramic-grain.map.png');
  map.colorSpace = THREE.SRGBColorSpace;
  map.wrapS = THREE.ClampToEdgeWrapping;
  map.wrapT = THREE.ClampToEdgeWrapping;

  material.map = null;
  material.colorNode = texture(map, atlasUV);

  const mesh = new THREE.Mesh(geometry, material);
  mesh.name = 'hub-features-title-plane';
  group.add(mesh);

  // Billboard behavior: orient toward camera each frame.
  group.userData.onBeforeRender = (renderer, scene, camera) => {
    mesh.quaternion.copy(camera.quaternion);
  };

  // Render "Features" headline text via MSDF font atlas, layered above the surface plane.
  let textMesh = null;
  if (config.textContent && ctx.fontAtlas) {
    textMesh = ctx.fontAtlas.createText({
      text: 'Features',
      font: 'Lora',
      weight: 400,
      size: 0.34,
      color: config.visual?.colors?.paper || '#e8ecf2',
      anchor: 'center',
    });
    if (textMesh) {
      textMesh.position.set(0, 0, 0.001);
      group.add(textMesh);
      group.userData.onBeforeRenderText = (renderer, scene, camera) => {
        textMesh.quaternion.copy(camera.quaternion);
      };
    }
  }

  group.userData.handlers = {};

  group.userData.cleanup = () => {
    geometry.dispose();
    material.dispose();
    if (map && map.dispose) map.dispose();
    if (textMesh && textMesh.userData && typeof textMesh.userData.cleanup === 'function') {
      textMesh.userData.cleanup();
    }
    disposers.forEach((fn) => fn());
  };

  return group;
}
